<script setup>
import { computed, onMounted, ref } from 'vue'
import { CircleCheck, CircleClose, Clock, Document, Refresh, Tickets } from '@element-plus/icons-vue'
import { api } from '../api'
import '../customer-workbench.css'

const loading = ref(true); const saving = ref(false); const error = ref(''); const message = ref('')
const data = ref({ customer: null, demands: [], leads: [] }); const historyVisible = ref(false); const events = ref([]); const eventLoading = ref(false); const selectedLead = ref(null)
const statusLabels = { NEW: '待匹配', MATCHED: '候选对接', CONTACTED: '已进入对接', INTENT: '有意向', WON: '已成交', LOST: '已关闭' }
const statusTypes = { MATCHED: 'primary', CONTACTED: 'primary', INTENT: 'warning', WON: 'success', LOST: 'info' }
const confirmation = value => value === 'ACCEPTED' ? '已确认' : value === 'DECLINED' ? '暂不对接' : '待确认'
const confirmationType = value => value === 'ACCEPTED' ? 'success' : value === 'DECLINED' ? 'info' : 'warning'
const formatDate = value => value ? new Date(value).toLocaleString('zh-CN', { hour12: false }) : '未设置'
const activeLeads = computed(() => data.value.leads.filter(item => !['WON', 'LOST'].includes(item.status)).length)
async function messageFor(response, fallback) { try { return (await response.json()).message || fallback } catch { return fallback } }
async function load() { loading.value = true; error.value = ''; try { const response = await api('/api/workbench/customer'); if (!response.ok) throw new Error(await messageFor(response, '客户工作台加载失败')); data.value = await response.json() } catch (e) { error.value = e.message } finally { loading.value = false } }
async function confirm(row, accepted) { saving.value = true; error.value = ''; message.value = ''; try { const response = await api(`/api/workbench/customer/leads/${row.id}/confirmation`, { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ accepted }) }); if (!response.ok) throw new Error(await messageFor(response, '联系意向确认失败')); message.value = accepted ? '已确认对接，等待供应商确认后开放联系通道。' : '已标记为暂不对接。'; await load() } catch (e) { error.value = e.message } finally { saving.value = false } }
async function openHistory(row) { selectedLead.value = row; events.value = []; historyVisible.value = true; eventLoading.value = true; try { const response = await api(`/api/workbench/customer/leads/${row.id}/events`); if (!response.ok) throw new Error(await messageFor(response, '事件记录加载失败')); events.value = await response.json() } catch (e) { error.value = e.message } finally { eventLoading.value = false } }
onMounted(load)
</script>

<template>
  <section class="customer-workbench" v-loading="loading">
    <header class="customer-heading"><div><h1>客户工作台</h1><p v-if="data.customer">{{ data.customer.organization || data.customer.contactName }}的采购需求、候选对接和过程记录</p><p v-else>完善联系人档案后提交采购需求，平台将为您生成候选对接。</p></div><div class="customer-actions"><el-button :icon="Refresh" @click="load">刷新</el-button><RouterLink class="el-button el-button--primary" to="/demand/new">提交新需求</RouterLink></div></header>
    <el-alert v-if="error" :title="error" type="error" show-icon closable @close="error=''" /><el-alert v-if="message" :title="message" type="success" show-icon closable @close="message=''" />
    <template v-if="!loading && !data.customer"><section class="customer-empty"><el-icon><Document /></el-icon><h2>尚未建立客户联系人档案</h2><p>提交首个采购需求时即可保存联系人信息，并开始生成候选供应商。</p><RouterLink class="primary-button" to="/demand/new">提交采购需求</RouterLink></section></template>
    <template v-else-if="data.customer"><div class="customer-summary"><div><span>已提交需求</span><strong>{{ data.demands.length }}</strong></div><div><span>待推进对接</span><strong>{{ activeLeads }}</strong></div><div><span>已达成意向</span><strong>{{ data.leads.filter(item => ['INTENT','WON'].includes(item.status)).length }}</strong></div><p><el-icon><Tickets /></el-icon> 联系方式仅在客户和供应商均确认后向供应商开放。</p></div>
      <section class="customer-section"><div class="section-heading"><div><h2>采购需求</h2><p>系统会对已审核供应商方案进行分类和标签匹配。</p></div><RouterLink class="el-button" to="/demand/new">新增需求</RouterLink></div><el-table :data="data.demands" empty-text="暂未提交采购需求"><el-table-column prop="title" label="需求标题" min-width="260" /><el-table-column label="预算级别" width="116"><template #default="{ row }">{{ row.budgetLevel || '待沟通' }}</template></el-table-column><el-table-column label="状态" width="120"><template #default="{ row }"><el-tag :type="statusTypes[row.status] || 'info'" effect="plain">{{ statusLabels[row.status] || row.status }}</el-tag></template></el-table-column><el-table-column label="提交时间" width="180"><template #default="{ row }">{{ formatDate(row.createdAt) }}</template></el-table-column></el-table></section>
      <section class="customer-section"><div class="section-heading"><div><h2>候选对接</h2><p>确认联系意向后，供应商需单独确认；双方同意才会开始正式对接。</p></div></div><el-table :data="data.leads" empty-text="系统暂未匹配到候选供应商"><el-table-column prop="supplierName" label="供应商" min-width="210" /><el-table-column label="对应需求" min-width="210"><template #default="{ row }">{{ row.demandTitle }}</template></el-table-column><el-table-column label="匹配度" width="92"><template #default="{ row }">{{ row.matchScore == null ? '—' : `${row.matchScore}%` }}</template></el-table-column><el-table-column label="本方意向" width="110"><template #default="{ row }"><el-tag :type="confirmationType(row.customerConfirmation)" effect="plain">{{ confirmation(row.customerConfirmation) }}</el-tag></template></el-table-column><el-table-column label="供应商意向" width="120"><template #default="{ row }"><el-tag :type="confirmationType(row.supplierConfirmation)" effect="plain">{{ confirmation(row.supplierConfirmation) }}</el-tag></template></el-table-column><el-table-column label="进展" width="112"><template #default="{ row }"><el-tag :type="statusTypes[row.status] || 'info'" effect="plain">{{ statusLabels[row.status] || row.status }}</el-tag></template></el-table-column><el-table-column label="操作" width="190" fixed="right"><template #default="{ row }"><template v-if="row.status === 'MATCHED' && row.customerConfirmation === 'PENDING'"><el-button :icon="CircleCheck" link type="success" :loading="saving" @click="confirm(row, true)">确认对接</el-button><el-button :icon="CircleClose" link type="danger" :loading="saving" @click="confirm(row, false)">暂不对接</el-button></template><el-button :icon="Clock" link type="primary" @click="openHistory(row)">过程记录</el-button></template></el-table-column></el-table></section>
    </template>
    <el-dialog v-model="historyVisible" :title="selectedLead ? `${selectedLead.supplierName} · 对接记录` : '对接记录'" width="min(620px, 92vw)" class="lead-history-dialog"><el-timeline v-loading="eventLoading" v-if="events.length"><el-timeline-item v-for="event in events" :key="event.id" :timestamp="formatDate(event.createdAt)" :type="event.afterStatus === 'WON' ? 'success' : event.afterStatus === 'LOST' ? 'info' : 'primary'"><strong>{{ event.actorName }} · {{ event.action }}</strong><span v-if="event.remark">：{{ event.remark }}</span></el-timeline-item></el-timeline><el-empty v-else-if="!eventLoading" :image-size="54" description="尚无过程记录" /></el-dialog>
  </section>
</template>
